'use strict';

/** Error for malformed CSV input; `line` and `column` are 1-based. */
class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function checkDelimiter(delimiter) {
  if (typeof delimiter !== 'string' || delimiter.length !== 1 ||
      delimiter === '"' || delimiter === '\r' || delimiter === '\n') {
    throw new TypeError('delimiter must be a single character other than ", CR or LF');
  }
}

/**
 * Parses CSV text into records (arrays of strings, or objects with
 * `options.header`). Options: delimiter, header, skipEmptyLines.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  if (options === null || typeof options !== 'object') throw new TypeError('options must be an object');
  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
  checkDelimiter(delimiter);
  const useHeader = options.header === true;
  const skipEmpty = options.skipEmptyLines === true;

  let pos = text.charCodeAt(0) === 0xfeff ? 1 : 0;
  const n = text.length;
  let line = 1;
  let lineStart = pos;
  const records = [];
  let header = null;

  const newline = () => {
    if (text[pos] === '\r' && text[pos + 1] === '\n') pos++;
    pos++;
    line++;
    lineStart = pos;
  };

  while (pos < n) {
    const ch = text[pos];
    if (ch === '\r' || ch === '\n') {
      if (!skipEmpty) addRecord([''], line);
      newline();
      continue;
    }
    const recordLine = line;
    const fields = [];
    const starts = [];
    for (;;) {
      starts.push([line, pos - lineStart + 1]);
      if (text[pos] === '"') {
        const openLine = line;
        const openCol = pos - lineStart + 1;
        pos++;
        let value = '';
        for (;;) {
          let next = pos;
          while (next < n && text[next] !== '"' && text[next] !== '\r' && text[next] !== '\n') next++;
          value += text.slice(pos, next);
          pos = next;
          if (pos >= n) throw new CsvError('unterminated quoted field', openLine, openCol);
          if (text[pos] === '"') {
            if (text[pos + 1] === '"') { value += '"'; pos += 2; continue; }
            pos++;
            break;
          }
          value += text[pos] === '\r' && text[pos + 1] === '\n' ? '\r\n' : text[pos];
          newline();
        }
        fields.push(value);
        const after = text[pos];
        if (pos < n && after !== delimiter && after !== '\r' && after !== '\n') {
          throw new CsvError('unexpected character after closing quote', line, pos - lineStart + 1);
        }
      } else {
        let next = pos;
        while (next < n && text[next] !== delimiter && text[next] !== '\r' && text[next] !== '\n') next++;
        fields.push(text.slice(pos, next));
        pos = next;
      }
      if (pos < n && text[pos] === delimiter) { pos++; continue; }
      break;
    }
    addRecord(fields, recordLine, starts);
    if (pos < n) newline();
  }

  function addRecord(fields, recordLine, starts) {
    if (!useHeader) { records.push(fields); return; }
    if (header === null) {
      const seen = new Set();
      fields.forEach((name, i) => {
        if (seen.has(name)) throw new CsvError(`duplicate header name "${name}"`, starts ? starts[i][0] : recordLine, starts ? starts[i][1] : 1);
        seen.add(name);
      });
      header = fields;
      return;
    }
    if (fields.length !== header.length) {
      throw new CsvError(`expected ${header.length} fields but found ${fields.length}`, recordLine, 1);
    }
    const obj = {};
    header.forEach((name, i) => { obj[name] = fields[i]; });
    records.push(obj);
  }

  return records;
}

/**
 * Serializes records to CSV text. Options: delimiter, eol ('\r\n' or '\n'),
 * header (array of column names; enables object records).
 */
function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');
  if (options === null || typeof options !== 'object') throw new TypeError('options must be an object');
  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
  checkDelimiter(delimiter);
  const eol = options.eol === undefined ? '\r\n' : options.eol;
  if (eol !== '\r\n' && eol !== '\n') throw new TypeError("eol must be '\\r\\n' or '\\n'");
  const header = options.header;
  if (header !== undefined && (!Array.isArray(header) || header.some((h) => typeof h !== 'string'))) {
    throw new TypeError('header must be an array of strings');
  }

  const field = (value) => {
    let s;
    if (typeof value === 'string') s = value;
    else if (typeof value === 'number' || typeof value === 'boolean') s = String(value);
    else if (value === null || value === undefined) return '';
    else throw new TypeError(`unsupported value type: ${typeof value}`);
    if (s.includes(delimiter) || s.includes('"') || s.includes('\r') || s.includes('\n') ||
        s.startsWith(' ') || s.endsWith(' ')) {
      return `"${s.replace(/"/g, '""')}"`;
    }
    return s;
  };

  const lines = [];
  const write = (values) => {
    if (values.length === 1 && values[0] === '') lines.push('""');
    else lines.push(values.map(field).join(delimiter));
  };
  if (header) write(header);
  for (const row of rows) {
    if (Array.isArray(row)) write(row);
    else if (header && row !== null && typeof row === 'object') {
      write(header.map((key) => (Object.prototype.hasOwnProperty.call(row, key) ? row[key] : undefined)));
    } else throw new TypeError('each record must be an array (or an object when header is set)');
  }
  return lines.length ? lines.join(eol) + eol : '';
}

module.exports = { parse, stringify, CsvError };
