'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parse, CsvError } = require('../src/csv');

const err = (text, opts, line, column) =>
  assert.throws(() => parse(text, opts), (e) => e instanceof CsvError && e.line === line && e.column === column);

